import{_ as t,o as n,c as a,ah as o}from"./chunks/framework.ChH6X6u6.js";const p=JSON.parse('{"title":"Enrollment and payments","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/caissier/inscriptions-et-paiements.md","filePath":"src/en/guide/caissier/inscriptions-et-paiements.md"}'),s={name:"en/guide/caissier/inscriptions-et-paiements.md"};function i(r,e,l,d,c,h){return n(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="enrollment-and-payments" tabindex="-1">Enrollment and payments <a class="header-anchor" href="#enrollment-and-payments" aria-label="Permalink to &quot;Enrollment and payments&quot;">​</a></h1><p>This page covers the two moments where the cashier&#39;s office steps into a student&#39;s journey: entering a new application for a family visiting in person, and following the financial side of an already-enrolled student — fees, payments, discounts, and payment plan — under <strong>Billing</strong>.</p><h2 id="entering-an-application-for-a-family-on-site" tabindex="-1">Entering an application for a family on site <a class="header-anchor" href="#entering-an-application-for-a-family-on-site" aria-label="Permalink to &quot;Entering an application for a family on site&quot;">​</a></h2><p>When a family visits in person instead of filling in the online form, you&#39;re the one who submits their application.</p><ol><li>Open <strong>Students &amp; admissions → New application</strong>.</li><li>Enter the student&#39;s <strong>First name</strong>, <strong>Last name</strong>, <strong>Date of birth</strong> and, if you know it, <strong>Place of birth</strong> and <strong>Sex</strong>, then the desired <strong>Site</strong> and <strong>Department</strong>.</li><li>Add at least one <strong>Parent / guardian</strong>: first name, last name, email, phone (optional), and relationship (<strong>Father</strong>, <strong>Mother</strong>, <strong>Legal guardian</strong>, or <strong>Other</strong>). Check <strong>Primary contact</strong> for the person to contact first. Use <strong>Add guardian</strong> to enter more than one.</li><li>Click <strong>Submit application</strong>.</li></ol><p>This application joins the same queue as applications received online, tagged with the <strong>Cashier</strong> channel — the registrar&#39;s office reviews it and decides whether to assign it to a class. See <a href="/era-guide/en/guide/secretariat/candidatures.html">Applications</a>.</p><div class="tip custom-block"><p class="custom-block-title">Offline mode</p><p>If your workstation has no connection at the time, the form still works: the application is queued and sent automatically once the connection returns. You cannot attach documents while offline, though — add them once you&#39;re back online. A banner at the top of the page shows how many applications are waiting to sync, with a <strong>Sync now</strong> button as soon as you&#39;re back online.</p></div><h2 id="tracking-a-student-s-fees-and-payments" tabindex="-1">Tracking a student&#39;s fees and payments <a class="header-anchor" href="#tracking-a-student-s-fees-and-payments" aria-label="Permalink to &quot;Tracking a student&#39;s fees and payments&quot;">​</a></h2><p>Once an application is approved by the registrar&#39;s office, the student appears under <strong>Billing</strong>. The list can be filtered by student name and academic year, and shows each student&#39;s total due, total paid, and remaining balance. The <strong>Overdue</strong> button keeps only the students behind on their payment plan; for each of them, the overdue amount shows in red under the balance. A student who left during the year stays in the list, greyed out and marked &quot;Left on…&quot;: what they owe stays owed. Click <strong>View</strong> to open a student&#39;s full financial record.</p><p>The detail page shows four key figures: <strong>Total due</strong>, <strong>Discount</strong>, <strong>Total paid</strong>, and <strong>Balance</strong>.</p><h3 id="setting-the-fees-due" tabindex="-1">Setting the fees due <a class="header-anchor" href="#setting-the-fees-due" aria-label="Permalink to &quot;Setting the fees due&quot;">​</a></h3><p>If a fee structure exists for the student&#39;s site, department, and academic year, it appears under <strong>Fee items</strong>: mandatory items are listed directly, and optional items (for example cafeteria or transport) are offered as checkboxes.</p><p>Parents tick these services themselves from their space (see <a href="/era-guide/en/guide/parent/paiements-en-ligne.html">Online payments</a>): you find their choices here. For a family choosing at the desk, or to correct a special case — stopping the cafeteria during the year, for instance — tick or untick here, then click <strong>Save changes</strong>. Unlike a parent, the cash desk can remove a service already paid for.</p><p>For a student enrolled the previous year, a box recalls that year&#39;s options (for instance <strong>Options in 2025-2026: Cafeteria, …</strong>). The <strong>Use these options again</strong> button ticks the same items on this year&#39;s fee structure; an option missing from the new structure is flagged. Nothing is billed until you click <strong>Save changes</strong>: check with the family first.</p><p>If no fee structure is configured for this site, department, and academic year, the page tells you so — in that case, ask an administrator to create one before you can bill the student.</p><h3 id="collecting-a-payment" tabindex="-1">Collecting a payment <a class="header-anchor" href="#collecting-a-payment" aria-label="Permalink to &quot;Collecting a payment&quot;">​</a></h3><ol><li>In the <strong>Record a payment</strong> form, enter the <strong>Amount</strong>. It cannot be more than the student&#39;s remaining balance: as with an online payment, ERA refuses an overpayment.</li><li>Choose the <strong>Method</strong>: Cash, Mixx by Yass (formerly T-Money), Flooz, Card, Bank deposit, or Bank transfer.</li><li>If a fee structure exists, indicate which <strong>Fee item</strong> of the student&#39;s schedule this payment relates to, or leave the <strong>Lump sum (not tied to an item)</strong> choice for a payment that doesn&#39;t match any specific item.</li><li>Fill in the <strong>Reference</strong> (transaction number, check number, etc.) if you have one, the date the payment was <strong>paid</strong>, and any <strong>Notes</strong>.</li><li>Click <strong>Record payment</strong>.</li></ol><p>The payment appears in the student&#39;s <strong>Payments</strong> list, with a receipt generated automatically — click <strong>Download receipt</strong> on the payment&#39;s row to print it or hand it to the family. The student&#39;s guardians also receive a notification about the payment and the remaining balance.</p><p>To remove a payment entered by mistake, click <strong>Delete</strong> on its row and confirm — this action is permanent.</p><div class="tip custom-block"><p class="custom-block-title">Offline mode</p><p>A payment can be collected even without a connection: it appears in a <strong>Pending sync</strong> section until the connection returns, then syncs automatically (or via <strong>Sync now</strong>).</p></div><h4 id="offline-payments-to-check" tabindex="-1">Offline payments to check <a class="header-anchor" href="#offline-payments-to-check" aria-label="Permalink to &quot;Offline payments to check&quot;">​</a></h4><p>While the connection was down, the student&#39;s situation may have changed: a discount granted, a fee taken off the grid… A payment entered offline is <strong>always recorded</strong> when it syncs, since the money was collected, even if it would have been refused online. It is then flagged:</p><ul><li><strong>Exceeded what was left to pay</strong>: the surplus becomes the family&#39;s credit (see <a href="#refunding-a-credit">Refunding a credit</a>).</li><li><strong>The fee chosen is no longer on the grid</strong>: the payment is recorded without a specific fee.</li></ul><p>These payments are listed at the top of the <strong>Billing</strong> page, in the <strong>offline payment(s) to check</strong> block, with a link to each student. On the student&#39;s page, the payment carries a <strong>Sync conflict</strong> badge and the reason. Do what is needed (refund the credit, tell the family…), then click <strong>Mark as resolved</strong>: the badge becomes <strong>Conflict resolved</strong>, with who resolved it and when.</p><h3 id="setting-up-a-payment-plan" tabindex="-1">Setting up a payment plan <a class="header-anchor" href="#setting-up-a-payment-plan" aria-label="Permalink to &quot;Setting up a payment plan&quot;">​</a></h3><p>To spread a student&#39;s fees over several installments instead of waiting for a single payment:</p><ol><li>In the <strong>Payment plan</strong> section, click <strong>Add installment</strong> for each installment you want.</li><li>For each installment, fill in a <strong>Label</strong> (for example &quot;1st installment&quot;), an <strong>Amount</strong>, and a <strong>Due date</strong>.</li><li>Click <strong>Save payment plan</strong>.</li></ol><p>Each installment then shows a status: <strong>Upcoming</strong>, <strong>Paid</strong>, or <strong>Overdue</strong>, based on the due date and payments already received. An installment becomes overdue the day after its due date if payments don&#39;t cover it yet. The plan follows what is actually due: if a discount is granted or a service added or dropped after it was set up, the installments are adjusted. A decrease is taken off starting from the last installment; an increase is added to the last one. The originally planned amount stays shown under the new one (&quot;planned: …&quot;), and overdue amounts are worked out on the new amount. Setting up a new plan automatically replaces the previous one, if there was one. To delete a plan without replacing it, click <strong>Delete</strong> above the installments table and confirm.</p><h3 id="viewing-and-applying-a-discount" tabindex="-1">Viewing and applying a discount <a class="header-anchor" href="#viewing-and-applying-a-discount" aria-label="Permalink to &quot;Viewing and applying a discount&quot;">​</a></h3><p>Discounts granted to a student (label, fixed amount or percentage, reason, and who granted it) are visible to everyone in the <strong>Discounts</strong> section of the financial record.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Granting or removing a discount is reserved for administrator accounts. If you&#39;re signed in as cashier, you&#39;ll see existing discounts but not the <strong>Grant a discount</strong> form — ask an administrator to open the same record to add one:</p><ol><li>Enter a <strong>Label</strong> for the discount (what it represents).</li><li>Choose the <strong>Type</strong>: <strong>Fixed amount</strong> or <strong>Percentage</strong>.</li><li>Enter the corresponding <strong>Value</strong>.</li><li>Enter the <strong>Reason</strong> for the discount (optional).</li><li>Click <strong>Grant discount</strong>.</li></ol></div><p>A granted discount does not change the <strong>Total due</strong>, which stays the sum of the fees: it shows under <strong>Discount</strong> and immediately lowers the <strong>Balance</strong>. For instance, with 300,000 in fees, a 50,000 discount and 100,000 already paid, the balance is 150,000.</p><h3 id="refunding-a-credit" tabindex="-1">Refunding a credit <a class="header-anchor" href="#refunding-a-credit" aria-label="Permalink to &quot;Refunding a credit&quot;">​</a></h3><p>When a family has paid more than it now owes (a discount granted or a service dropped after the payment), the <strong>Balance</strong> card becomes <strong>Credit</strong>, in green, with the amount in the family&#39;s favour. The <strong>Billing</strong> list shows it too.</p><p>The <strong>Credit and refunds</strong> section then appears. You can leave the credit in place or hand the money back:</p><ol><li>Check the <strong>Amount</strong> (prefilled with the credit; it can&#39;t exceed it).</li><li>Choose the <strong>Method</strong> used for the refund.</li><li>Fill in <strong>Refunded on</strong>, and if needed a <strong>Reference</strong> and a <strong>Reason</strong>.</li><li>Click <strong>Record the refund</strong>.</li></ol><p>The refund shows in the section&#39;s list, with who entered it. The <strong>Total paid</strong> card says &quot;of which … refunded&quot;. Deleting a refund entered by mistake gives the family its credit back.</p><p>Refunds leave the till: they appear as a negative line in the payments CSV export, in journal <strong>DC</strong> in the SYSCOHADA export (the reverse of the payment&#39;s entry), and they come off the amount collected in pilotage.</p>',38)])])}const u=t(s,[["render",i]]);export{p as __pageData,u as default};
